{
  "name": "neon",
  "version": "0.3.0",
  "private": true,
  "type": "module",
  "description": "NÉON — a minimalist neon brick breaker, zero dependencies.",
  "scripts": {
    "serve": "node serve.js",
    "test": "node --test \"game/**/*.test.js\""
  }
}

// neon.js — NÉON, a minimalist brick breaker (zero dependencies).
//
// This file INTENTIONALLY mixes game logic and rendering in a few places
// (see ISSUES.md #2): brick collision detection currently lives inside the
// draw loop `frame()`. This is deliberate debt, ripe for a refactor.
//
// The module runs nothing on import: only `boot()` touches the DOM. Pure
// logic can therefore be imported from the tests (`node --test`) without a
// browser.

import { palette, brickColor } from './theme.js';
import { createGlowMap, drawGlow, GLOW_W, GLOW_H } from './bloom.js';

// --- Axis convention -------------------------------------------------------

// Screen coordinates, as the canvas defines them: the origin is the TOP-LEFT
// corner and **Y GROWS DOWNWARD**. So `y = 0` is the ceiling, `y = HEIGHT` the
// line through which the ball is lost, and a ball climbing toward the bricks
// has a NEGATIVE `vy`. Every sign in this file follows from that single
// choice — the launch velocity, each bounce, and the paddle test `vy > 0`.
//
// The constants below name the sign a velocity component takes per heading.
// Assert against them rather than against a bare `-1` / `1`: a test reading
// `Math.sign(ball.vy) === UP` states its intent, where a hard-coded `-1` only
// states an arithmetic fact and quietly means the opposite if the convention
// ever flips.
//
//   UP    (-1)  toward the ceiling and the bricks
//   DOWN  (+1)  toward the paddle and the loss line
//   LEFT  (-1)  toward x = 0
//   RIGHT (+1)  toward x = WIDTH

export const UP = -1;
export const DOWN = 1;
export const LEFT = -1;
export const RIGHT = 1;

// --- Field constants -------------------------------------------------------

export const WIDTH = 640;
export const HEIGHT = 480;

export const PADDLE_W = 96;
export const PADDLE_H = 12;
export const PADDLE_Y = HEIGHT - 32;

export const BALL_R = 7;

export const BRICK_ROWS = 5;
export const BRICK_COLS = 8;
export const BRICK_W = 72;
export const BRICK_H = 20;
export const BRICK_GAP = 8;
export const BRICK_TOP = 48;

const STORAGE_KEY = 'neon.best';

// --- State construction ----------------------------------------------------

// Builds the brick grid for a given level.
// The higher the level, the more points bricks are worth.
export function makeBricks(level = 1) {
  const bricks = [];
  const offsetX = (WIDTH - (BRICK_COLS * (BRICK_W + BRICK_GAP) - BRICK_GAP)) / 2;
  for (let row = 0; row < BRICK_ROWS; row++) {
    for (let col = 0; col < BRICK_COLS; col++) {
      bricks.push({
        x: offsetX + col * (BRICK_W + BRICK_GAP),
        y: BRICK_TOP + row * (BRICK_H + BRICK_GAP),
        w: BRICK_W,
        h: BRICK_H,
        row,
        alive: true,
        points: (BRICK_ROWS - row) * 10 * level,
      });
    }
  }
  return bricks;
}

// Ball speed as a function of the level (ramps up with each level).
export function ballSpeed(level = 1) {
  return 260 + (level - 1) * 90;
}

// Creates a fresh game state.
export function createState(level = 1) {
  const speed = ballSpeed(level);
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball: { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed },
    bricks: makeBricks(level),
  };
}

// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// --- Score & combo (NOT covered by tests — debt #5) ------------------------

// Combo multiplier. UNBOUNDED today: a long combo makes the score blow up
// uncontrollably (see #5, expected improvement = clamp it).
export function comboMultiplier(combo) {
  return 1 + combo * 0.5;
}

// Points earned for breaking a brick, combo included.
export function scoreForBrick(brick, combo) {
  return Math.round(brick.points * comboMultiplier(combo));
}

// --- Best score persistence ------------------------------------------------

// Reads the best score from a localStorage-compatible storage.
// Robust to corrupted or missing storage: returns 0 instead of throwing.
export function loadBest(storage) {
  if (!storage) return 0;
  try {
    const raw = storage.getItem(STORAGE_KEY);
    const value = Number.parseInt(raw, 10);
    return Number.isFinite(value) && value > 0 ? value : 0;
  } catch {
    return 0;
  }
}

// Writes the best score if the current score beats it. Returns the updated best.
export function saveBest(storage, score) {
  const best = loadBest(storage);
  if (score > best && storage) {
    try {
      storage.setItem(STORAGE_KEY, String(score));
    } catch {
      // storage unavailable (private mode, quota): silently ignore
    }
    return score;
  }
  return best;
}

// --- Physics (movement + wall/paddle bounces) ------------------------------

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Does NOT handle bricks: that responsibility still
// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

// --- Rendering (DOM): brick collision logic STILL mixed in here ------------

// Main render loop. For each live brick we test collision AND draw in the same
// pass: this is where logic and rendering are entangled.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: collision + bounce + score + drawing, all in one place.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    if (collides(state.ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      // BUG (#1): the ball is NOT deflected here. Only the walls and the paddle
      // bounce (in step()); bricks were never given a bounce. So the ball plows
      // straight through a column head-on AND straight through the side of a
      // row. Fix = a real per-face bounce (flip vy on a top/bottom hit, vx on a
      // side hit) plus pushing the ball back out of the brick.
    }

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

  // Paddle — color hard-coded instead of using the palette (inconsistency #6).
  ctx.fillStyle = '#00e5ff';
  ctx.fillRect(state.paddle.x, state.paddle.y, state.paddle.w, state.paddle.h);

  // Ball — also hard-coded (#6).
  ctx.fillStyle = '#39ff14';
  ctx.beginPath();
  ctx.arc(state.ball.x, state.ball.y, state.ball.r, 0, Math.PI * 2);
  ctx.fill();

  // HUD
  ctx.fillStyle = palette.text;
  ctx.font = '16px monospace';
  ctx.fillText(`Score ${state.score}`, 12, 24);
  ctx.fillText(`Best ${state.best}`, WIDTH - 110, 24);
  ctx.fillText(`Lives ${state.lives}`, WIDTH / 2 - 30, 24);
}

// --- Boot (browser entry point) --------------------------------------------

// Starts the game: wires up the canvas, the mouse and the animation loop.
// The only function that depends on the DOM; never called on import.
export function boot(doc = document) {
  const canvas = doc.getElementById('game');
  const ctx = canvas.getContext('2d');
  canvas.width = WIDTH;
  canvas.height = HEIGHT;

  const state = createState(1);
  state.best = loadBest(doc.defaultView?.localStorage ?? globalThis.localStorage);
  state.running = true;

  // Glow pass: a coarse offscreen light map, stretched over the field.
  const offscreen = doc.createElement('canvas');
  offscreen.width = GLOW_W;
  offscreen.height = GLOW_H;
  const glow = {
    map: createGlowMap(),
    image: offscreen.getContext('2d').createImageData(GLOW_W, GLOW_H),
  };

  // Move the paddle with the mouse.
  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left - state.paddle.w / 2;
    state.paddle.x = Math.max(0, Math.min(WIDTH - state.paddle.w, x));
  });

  let last = performance.now();
  function loop(now) {
    const dt = Math.min((now - last) / 1000, 0.05);
    last = now;

    if (state.running) {
      const lost = step(state, dt);
      if (lost) {
        state.lives -= 1;
        state.combo = 0;
        if (state.lives <= 0) {
          state.best = saveBest(globalThis.localStorage, state.score);
          Object.assign(state, createState(state.level));
          state.best = loadBest(globalThis.localStorage);
        } else {
          // relaunch the ball
          state.ball = createState(state.level).ball;
        }
      }

      // Level cleared: all bricks broken
      if (state.bricks.every((b) => !b.alive)) {
        state.level += 1;
        state.bricks = makeBricks(state.level);
        state.ball = createState(state.level).ball;
      }
    }

    frame(ctx, state);
    drawGlow(ctx, glow, state, WIDTH, HEIGHT, offscreen);
    requestAnimationFrame(loop);
  }
  requestAnimationFrame(loop);

  return state;
}

// neon.test.js — PARTIAL coverage (on purpose).
//
// What is covered today: the collision primitive and a couple of physics
// bounces. What is NOT covered yet: score and combo (see ISSUES.md #5), nor
// level progression. This is a starting point for the testing work ahead, not
// a complete suite.
//
// Run: `node --test "game/**/*.test.js"`  (or `npm test`)

import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: belowField(), r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// Small local helper: place the ball below the field without importing the
// height (coverage intentionally light).
function belowField() {
  return 500;
}

// TODO (#5): test comboMultiplier / scoreForBrick.
// TODO      : test level progression and loadBest/saveBest persistence.

// sonde.test.js - les cas limites de l'issue #1, en tests exécutables, **donnés d'avance**.
//
// Ce fichier n'existe pas à l'étalon. Une brique `kind = "files"` du scénario le dépose dans
// l'arbre mesuré avant que l'agent démarre, et le commite sur l'étalon : la cellule qui le
// reçoit commence donc son travail avec la suite rouge et la spécification sous les yeux.
// C'est tout ce que cette cellule mesure - un modèle qui a déjà les tests qu'il faut
// se corrige-t-il ?
//
// ---------------------------------------------------------------------------
// CE QU'IL FAUT FAIRE POUR QUE CE FICHIER PUISSE SEULEMENT TOURNER
//
// Il importe `frame` depuis `./neon.js`, que le module **n'exporte pas** aujourd'hui. Tant
// que ce n'est pas le cas, `npm test` échoue au chargement du module et aucun cas ne joue.
// Exporter la boucle de rendu est donc la première chose à faire, et c'est une ligne.
// ---------------------------------------------------------------------------
//
// Quinze cas, en six groupes. Les quatre premiers sont l'issue #1, du plus grossier au plus
// fin, et chacun noircit une forme de correction incomplète que le précédent laissait passer :
//
//   `brique`   les quatre faces : l'axe touché s'inverse, l'autre ne bouge pas.
//   `angle`    le coin : les deux composantes s'inversent. Une correction par face échoue ici.
//   `sortie`   la balle est ressortie du rectangle. C'est la seconde moitié de ce que le
//              commentaire de `neon.js` décrit lui-même : « plus pushing the ball back out of
//              the brick ». Une correction qui inverse sans repositionner laisse le rebond
//              collant - au tour suivant la balle recouvre encore et se ré-inverse.
//   `voisines` deux briques touchées dans la même passe : le rebond s'applique une fois et pas
//              deux. Un `vy = -vy` appliqué deux fois s'annule et la balle traverse. Le gap de
//              la grille est de 8 px et le diamètre de la balle de 14, donc toute couture de la
//              grille est un double recouvrement : c'est le cas courant, pas la curiosité.
//
// Les deux derniers sont **d'autres bugs que l'issue #1 ne mentionne pas**, trouvés en écrivant
// les cas ci-dessus. Ils sont ici parce qu'ils vivent dans la même détection de collision et
// qu'un fichier de cas limites qui les taît serait mensonger, pas parce que le ticket les
// commande :
//
//   `traversee` la balle rapide saute par-dessus la brique sans jamais la toucher. La détection
//               est discrète : elle échantillonne la position avant et après le déplacement, et
//               à la vitesse du niveau 6 le déplacement d'une frame dépasse la hauteur d'une
//               brique. Seule une détection continue - un balayage entre les deux positions -
//               fait passer ce cas.
//
// Ce sont des tests `node:test` ordinaires, comme `game/neon.test.js`, lancés par la commande
// de `npm test`. Rien ici n'est une convention du harnais.

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';

// Un import, et non un `typeof` sur chaque nom : si l'un d'eux manque, le module ne se lie
// pas, aucun cas ne tourne, et l'échec dit *quel* nom manquait. C'est le bon message.
import {
  frame,
  step,
  createState,
  ballSpeed,
  WIDTH,
  HEIGHT,
  BALL_R,
  BRICK_W,
  BRICK_H,
  BRICK_GAP,
} from './neon.js';

// Le pas de temps d'une frame nominale, et le plafond que `boot()` applique sur une frame qui a
// bégayé. Les quatre premiers groupes n'en ont pas besoin - leur balle est déjà en recouvrement -
// mais `traversee` juge la détection *pendant* le déplacement, et c'est
// exactement ce que ces deux valeurs-là produisent dans le jeu.
const DT = 1 / 60;
const DT_MAX = 0.05;

// Chaque cas des quatre premiers groupes pose une balle **déjà en recouvrement** avec la brique,
// de 3 px par la face visée et de 17 px ou plus par l'autre axe. Rien n'avance d'un pas de temps
// pour *atteindre* la brique, donc rien ne dépend d'un `dt`. La vitesse hors axe est petite mais
// non nulle, pour qu'une correction qui inverse les deux axes à tout hasard échoue au lieu de
// passer.

describe('brique', () => {
  test('flanc gauche: la balle repart vers la gauche', (t) => {
    const state = createState(1);
    state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
    state.ball = { x: 96, y: 110, r: BALL_R, vx: 300, vy: 30 };

    jouer(t, state);

    assert.ok(state.ball.vx < 0, `vx devait devenir négatif : ${state.ball.vx}`);
    assert.ok(state.ball.vy > 0, `vy devait rester positif : ${state.ball.vy}`);
  });

  test('flanc droit: la balle repart vers la droite', (t) => {
    const state = createState(1);
    state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
    state.ball = { x: 176, y: 110, r: BALL_R, vx: -300, vy: 30 };

    jouer(t, state);

    assert.ok(state.ball.vx > 0, `vx devait devenir positif : ${state.ball.vx}`);
    assert.ok(state.ball.vy > 0, `vy devait rester positif : ${state.ball.vy}`);
  });

  test('face haute: la balle repart vers le haut', (t) => {
    const state = createState(1);
    state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
    state.ball = { x: 136, y: 96, r: BALL_R, vx: 30, vy: 300 };

    jouer(t, state);

    assert.ok(state.ball.vy < 0, `vy devait devenir négatif : ${state.ball.vy}`);
    assert.ok(state.ball.vx > 0, `vx devait rester positif : ${state.ball.vx}`);
  });

  test('face basse: la balle repart vers le bas', (t) => {
    const state = createState(1);
    state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
    state.ball = { x: 136, y: 124, r: BALL_R, vx: 30, vy: -300 };

    jouer(t, state);

    assert.ok(state.ball.vy > 0, `vy devait devenir positif : ${state.ball.vy}`);
    assert.ok(state.ball.vx > 0, `vx devait rester positif : ${state.ball.vx}`);
  });
});

// Sur le coin, la balle arrive par la diagonale et pénètre autant sur les deux axes : les deux
// composantes doivent s'inverser. Une correction qui compare les deux pénétrations et n'en
// inverse qu'une passe les quatre faces et échoue ici.

describe('angle', () => {
  test('coin haut gauche: la balle repart en diagonale', (t) => {
    const state = createState(1);
    state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
    state.ball = { x: 96, y: 96, r: BALL_R, vx: 300, vy: 300 };

    jouer(t, state);

    assert.ok(state.ball.vx < 0, `vx devait devenir négatif : ${state.ball.vx}`);
    assert.ok(state.ball.vy < 0, `vy devait devenir négatif : ${state.ball.vy}`);
  });
});

// Le miroir géométrique de `brique` : mêmes quatre fixtures, mais on n'observe plus la vitesse,
// on observe la **position**.
//
// L'assertion est arithmétique et **pas** `!collides(ball, brick)` : `collides` fait partie du
// code sous test, et juger avec sa propre définition rendrait le cas plus facile pour une
// correction qui l'aurait assouplie. La tolérance couvre un calcul de pénétration en flottants
// qui atterrit à un ulp du bord.
const EPS = 1e-9;

describe('sortie', () => {
  test('flanc gauche: la balle ressort par la gauche', (t) => {
    const state = createState(1);
    state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
    state.ball = { x: 96, y: 110, r: BALL_R, vx: 300, vy: 30 };

    jouer(t, state);

    const bord = state.ball.x + BALL_R;
    assert.ok(bord <= 100 + EPS, `le bord droit de la balle devait revenir à x <= 100 : ${bord}`);
  });

  test('flanc droit: la balle ressort par la droite', (t) => {
    const state = createState(1);
    state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
    state.ball = { x: 176, y: 110, r: BALL_R, vx: -300, vy: 30 };

    jouer(t, state);

    const bord = state.ball.x - BALL_R;
    assert.ok(bord >= 172 - EPS, `le bord gauche de la balle devait revenir à x >= 172 : ${bord}`);
  });

  test('face haute: la balle ressort par le haut', (t) => {
    const state = createState(1);
    state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
    state.ball = { x: 136, y: 96, r: BALL_R, vx: 30, vy: 300 };

    jouer(t, state);

    const bord = state.ball.y + BALL_R;
    assert.ok(bord <= 100 + EPS, `le bord bas de la balle devait revenir à y <= 100 : ${bord}`);
  });

  test('face basse: la balle ressort par le bas', (t) => {
    const state = createState(1);
    state.bricks = [{ x: 100, y: 100, w: BRICK_W, h: BRICK_H, row: 0, alive: true, points: 10 }];
    state.ball = { x: 136, y: 124, r: BALL_R, vx: 30, vy: -300 };

    jouer(t, state);

    const bord = state.ball.y - BALL_R;
    assert.ok(bord >= 120 - EPS, `le bord haut de la balle devait revenir à y >= 120 : ${bord}`);
  });
});

// Deux briques touchées dans la **même passe** de la boucle, qui parcourt toutes les briques
// vivantes. Le rebond doit s'appliquer une fois. Trois formes de correction se séparent ici :
// `vy = -vy` s'annule au second tour et la balle traverse ; `vy = Math.abs(vy)` est idempotente
// et passe ; une correction qui repositionne sort la balle du recouvrement avant d'atteindre la
// seconde brique et passe aussi.
//
// Chaque fixture est réglée pour que la face visée soit sans ambiguïté la **plus faible
// pénétration** - 1 px contre 3 sur l'axe de la couture - afin qu'un résolveur par pénétration
// minimale n'ait aucun choix à faire et que l'échec ne puisse venir que du double comptage.
//
// Les vitesses sont dix fois plus faibles qu'ailleurs, et c'est délibéré : une correction placée
