// --- Brick collision (resolution) -----------------------------------------

// Penetration depths of the ball's box against a brick, on each axis.
function depths(ball, brick) {
  return {
    x: Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r)),
    y: Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r)),
  };
}

// Face and axis for a positional overlap: the axis of smallest penetration
// (minimum translation vector); a tie means a corner hit, both axes flip.
function faceByDepth(ball, brick) {
  const d = depths(ball, brick);
  if (d.x < d.y) {
    return { axis: 'x', face: ball.x < brick.x + brick.w / 2 ? 'left' : 'right' };
  }
  if (d.y < d.x) {
    return { axis: 'y', face: ball.y < brick.y + brick.h / 2 ? 'top' : 'bottom' };
  }
  return { axis: 'corner', face: 'corner' };
}

// Swept AABB test (slab method): does the segment (px,py) -> (x,y) hit the
// brick expanded by the ball radius? Returns the axis (and face) of the hit,
// or null. Positional overlaps (the segment starts inside the expanded box)
// are resolved by depth, crossings during the step by the slab entry times.
function sweptHit(ball, brick) {
  const { px, py } = ball;
  const dx = ball.x - px;
  const dy = ball.y - py;

  const slabX0 = brick.x - ball.r;
  const slabX1 = brick.x + brick.w + ball.r;
  const slabY0 = brick.y - ball.r;
  const slabY1 = brick.y + brick.h + ball.r;

  let txIn, txOut;
  if (dx === 0) {
    if (px < slabX0 || px > slabX1) return null;
    txIn = -Infinity;
    txOut = Infinity;
  } else {
    txIn = Math.min((slabX0 - px) / dx, (slabX1 - px) / dx);
    txOut = Math.max((slabX0 - px) / dx, (slabX1 - px) / dx);
  }

  let tyIn, tyOut;
  if (dy === 0) {
    if (py < slabY0 || py > slabY1) return null;
    tyIn = -Infinity;
    tyOut = Infinity;
  } else {
    tyIn = Math.min((slabY0 - py) / dy, (slabY1 - py) / dy);
    tyOut = Math.max((slabY0 - py) / dy, (slabY1 - py) / dy);
  }

  const tClose = Math.max(txIn, tyIn);
  const tFar = Math.min(txOut, tyOut);
  if (tClose > tFar || tFar < 0 || tClose > 1) return null;

  if (tClose <= 0) {
    // Already overlapping at the start of the step: resolve positionally.
    return faceByDepth(ball, brick);
  }

  // Crossed during the step: the face entered last is the one hit.
