// Kills every brick the ball touches in this pass, pushes the ball back out
// of the rectangle and deflects it once per axis. One pass may overlap several
// bricks (the grid seams: BRICK_GAP is 8 px, smaller than the 14 px ball
// diameter), so the deflection must never be applied twice on the same axis.
function resolveBricks(state) {
  const { ball, bricks } = state;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = faceByDepth(ball, brick);
    if (!hit) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    if (hit.axis === 'x') ball.vx = -ball.vx;
    else if (hit.axis === 'y') ball.vy = -ball.vy;
    else {
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
    }
    // Push the ball back out of the brick, against the face it hit: an
    // inversion without repositioning leaves the ball overlapping the brick,
    // which re-triggers the bounce on the next pass (sticky ball).
    pushOut(ball, brick, hit.face);
  }
}

// Positions the ball so it just touches the face it hit, outside the brick.
function pushOut(ball, brick, face) {
  if (face === 'left') ball.x = brick.x - ball.r;
  else if (face === 'right') ball.x = brick.x + brick.w + ball.r;
  else if (face === 'top') ball.y = brick.y - ball.r;
  else if (face === 'bottom') ball.y = brick.y + brick.h + ball.r;
  else {
    // Corner: clear both axes, each toward its nearest face.
    ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
    ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  }
}

