function resolveBricks(state) {
  const { ball, bricks } = state;
  // One pass = at most one deflection per axis: two overlapping bricks on a
  // seam would otherwise invert the same velocity twice and cancel out.
  let flippedX = false;
  let flippedY = false;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const hit = faceByDepth(ball, brick);
    if (!hit) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    if (hit.axis === 'x' && !flippedX) {
      ball.vx = -ball.vx;
      flippedX = true;
    } else if (hit.axis === 'y' && !flippedY) {
      ball.vy = -ball.vy;
      flippedY = true;
    } else if (hit.axis === 'corner') {
      if (!flippedX) {
        ball.vx = -ball.vx;
        flippedX = true;
      }
      if (!flippedY) {
        ball.vy = -ball.vy;
        flippedY = true;
      }
    }
    // Push the ball back out of the brick, against the face it hit: an
    // inversion without repositioning leaves the ball overlapping the brick,
    // which re-triggers the bounce on the next pass (sticky ball).
    pushOut(ball, brick, hit.face);
  }
}

