// Swept AABB test (slab method): does the segment (px,py) -> (x,y) intersect
// the brick grown by the ball radius? A positional overlap (the segment starts
// inside the box) resolves by penetration depth; a crossing during the step
// resolves by the face entered last. Returns null when the segment misses the
// box entirely (including when the whole hit would happen after this step).
function sweptHit(ball, brick) {
  const { px, py } = ball;
  const dx = ball.x - px;
  const dy = ball.y - py;

  const x0 = brick.x - ball.r;
  const x1 = brick.x + brick.w + ball.r;
  const y0 = brick.y - ball.r;
  const y1 = brick.y + brick.h + ball.r;

  let txIn, txOut;
  if (dx === 0) {
    if (px < x0 || px > x1) return null;
    txIn = -Infinity;
    txOut = Infinity;
  } else {
    txIn = Math.min((x0 - px) / dx, (x1 - px) / dx);
    txOut = Math.max((x0 - px) / dx, (x1 - px) / dx);
  }

  let tyIn, tyOut;
  if (dy === 0) {
    if (py < y0 || py > y1) return null;
    tyIn = -Infinity;
    tyOut = Infinity;
  } else {
    tyIn = Math.min((y0 - py) / dy, (y1 - py) / dy);
    tyOut = Math.max((y0 - py) / dy, (y1 - py) / dy);
  }

  const tClose = Math.max(txIn, tyIn);
  const tFar = Math.min(txOut, tyOut);
  if (tClose > tFar || tFar < 0 || tClose > 1) return null;

  if (tClose <= 0) {
    // The ball already overlapped the brick at the start of the step.
    return faceByDepth(ball, brick);
  }

  // Crossed during the step: the face entered last is the face hit.
  if (txIn > tyIn) return { axis: 'x', face: dx > 0 ? 'left' : 'right' };
  if (tyIn > txIn) return { axis: 'y', face: dy > 0 ? 'top' : 'bottom' };
  return { axis: 'corner', face: 'corner' };
}

