@@ -206,6 +216,123 @@ export function step(state, dt) {
   return false;
 }

+// --- Brick collision (resolution) ------------------------------------------
+
+// Face and axis of a positional overlap: the axis of smallest penetration
+// (minimum translation vector) is the one hit; a tie means a corner, where
+// both axes are hit. Returns null when there is no overlap.
+function faceByDepth(ball, brick) {
+  const dx = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
+  const dy = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
+  if (dx <= 0 || dy <= 0) return null;
+  if (dx < dy) return { axis: 'x', face: ball.x < brick.x + brick.w / 2 ? 'left' : 'right' };
+  if (dy < dx) return { axis: 'y', face: ball.y < brick.y + brick.h / 2 ? 'top' : 'bottom' };
+  return { axis: 'corner', face: 'corner' };
+}
+
+// Swept AABB test (slab method): does the segment (px,py) -> (x,y) intersect
+// the brick grown by the ball radius? A positional overlap (the segment starts
+// inside the box) resolves by penetration depth; a crossing during the step
+// resolves by the face entered last. Returns null when the segment misses the
+// box entirely (including when the whole hit would happen after this step).
+function sweptHit(ball, brick) {
+  const { px, py } = ball;
+  const dx = ball.x - px;
+  const dy = ball.y - py;
+
+  const x0 = brick.x - ball.r;
+  const x1 = brick.x + brick.w + ball.r;
+  const y0 = brick.y - ball.r;
+  const y1 = brick.y + brick.h + ball.r;
+
+  let txIn, txOut;
+  if (dx === 0) {
+    if (px < x0 || px > x1) return null;
+    txIn = -Infinity;
+    txOut = Infinity;
+  } else {
+    txIn = Math.min((x0 - px) / dx, (x1 - px) / dx);
+    txOut = Math.max((x0 - px) / dx, (x1 - px) / dx);
+  }
+
+  let tyIn, tyOut;
+  if (dy === 0) {
+    if (py < y0 || py > y1) return null;
+    tyIn = -Infinity;
+    tyOut = Infinity;
+  } else {
+    tyIn = Math.min((y0 - py) / dy, (y1 - py) / dy);
+    tyOut = Math.max((y0 - py) / dy, (y1 - py) / dy);
+  }
+
+  const tClose = Math.max(txIn, tyIn);
+  const tFar = Math.min(txOut, tyOut);
+  if (tClose > tFar || tFar < 0 || tClose > 1) return null;
+
+  if (tClose <= 0) {
+    // The ball already overlapped the brick at the start of the step.
+    return faceByDepth(ball, brick);
+  }
+
+  // Crossed during the step: the face entered last is the face hit.
+  if (txIn > tyIn) return { axis: 'x', face: dx > 0 ? 'left' : 'right' };
+  if (tyIn > txIn) return { axis: 'y', face: dy > 0 ? 'top' : 'bottom' };
+  return { axis: 'corner', face: 'corner' };
+}
+
+// Kills every brick the ball touches in this pass, pushes the ball back out
+// of the rectangle and deflects it once per axis. One pass may overlap several
+// bricks (the grid seams: BRICK_GAP is 8 px, smaller than the 14 px ball
+// diameter), so the deflection must never be applied twice on the same axis.
+function resolveBricks(state) {
+  const { ball, bricks } = state;
+  // One pass = at most one deflection per axis: two overlapping bricks on a
+  // seam would otherwise invert the same velocity twice and cancel out.
+  let flippedX = false;
+  let flippedY = false;
+  for (const brick of bricks) {
+    if (!brick.alive) continue;
+    const hit = sweptHit(ball, brick);
+    if (!hit) continue;
+    brick.alive = false;
+    state.combo += 1;
+    state.score += scoreForBrick(brick, state.combo);
+    if (hit.axis === 'x' && !flippedX) {
+      ball.vx = -ball.vx;
+      flippedX = true;
+    } else if (hit.axis === 'y' && !flippedY) {
+      ball.vy = -ball.vy;
+      flippedY = true;
+    } else if (hit.axis === 'corner') {
+      if (!flippedX) {
