// lives in the render loop `frame()` (debt #2).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember the position before this step: the brick and paddle collision
  // tests below sweep the segment (previous -> new), not just the new sample.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Bricks: the bounce that frame() used to owe us (debt #2) is now pure
  // logic here, one step per physics pass.
  resolveBricks(state);

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle. The positional test samples a single point (ball.y + ball.r must
  // land inside the 12 px band), so a fast ball can cross the whole band in
  // one capped frame and be lost through the paddle: the swept test catches
  // the crossing of the top face between the previous and the new position.
  const bottom = ball.y + ball.r;
  const xOnPaddle = ball.x >= paddle.x && ball.x <= paddle.x + paddle.w;
  const inBand = bottom >= paddle.y && bottom <= paddle.y + paddle.h;
  const crossedTop = ball.vy > 0 && ball.py + ball.r < paddle.y && bottom >= paddle.y;
  if (ball.vy > 0 && xOnPaddle && (inBand || crossedTop)) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

