// Face and axis of a positional overlap: the axis of smallest penetration
// (minimum translation vector) is the one hit; a tie means a corner, where
// both axes are hit. Returns null when there is no overlap.
function faceByDepth(ball, brick) {
  const dx = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const dy = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));
  if (dx <= 0 || dy <= 0) return null;
  if (dx < dy) return { axis: 'x', face: ball.x < brick.x + brick.w / 2 ? 'left' : 'right' };
  if (dy < dx) return { axis: 'y', face: ball.y < brick.y + brick.h / 2 ? 'top' : 'bottom' };
  return { axis: 'corner', face: 'corner' };
}

